class TextLineStream:
    def __init__(self, file_obj: Any, encoding: str) -> None:
        self.decoder = codecs.getincrementaldecoder(encoding)(errors="replace")
        self.file_obj = file_obj
        self.buf = ""
        self.eof = False

    def __iter__(self) -> Iterable[str]:
        while True:
            if self.eof and not self.buf:
                return
            chunk = self.file_obj.read(1024 * 1024)
            if not chunk:
                self.eof = True
                text = self.decoder.decode(b"", final=True)
            else:
                text = self.decoder.decode(chunk, final=False)
            if text:
                self.buf += text
            while True:
                idx = self.buf.find("\n")
                if idx < 0:
                    break
                line = self.buf[:idx]
                self.buf = self.buf[idx + 1:]
                yield line
            if self.eof:
                if self.buf:
                    yield self.buf
                    self.buf = ""
                return

class TermMatcher:
    def __init__(self, terms: List[str]) -> None:
        self.terms = sorted(set(t.lower() for t in terms if t), key=len, reverse=True)
        self.regex = self._build_regex(self.terms)
        self.auto = None
        if _ahocorasick is not None:
            try:
                a = _ahocorasick.Automaton()
                for t in self.terms:
                    a.add_word(t, t)
                a.make_automaton()
                self.auto = a
            except Exception:
                self.auto = None

    def _build_regex(self, terms: List[str]) -> re.Pattern:
        parts = [re.escape(t) for t in terms if t]
        if not parts:
            return re.compile(r'^(?!)$')
        return re.compile(r'(' + "|".join(parts) + r')', re.IGNORECASE)

    def find_first(self, s_lower: str) -> Optional[str]:
        if self.auto is not None:
            try:
                for _, v in self.auto.iter(s_lower):
                    return v
            except Exception:
                pass
        m = self.regex.search(s_lower)
        if m:
            return m.group(1).lower()
        return None

class UnifiedLogExtractor:
    def __init__(self, output_dir: Path, max_entries: Optional[int], predicate: Optional[str], timeout_seconds: int) -> None:
        self.output_dir = output_dir
        self.max_entries = max_entries
        self.predicate = predicate
        self.timeout_seconds = timeout_seconds

    def is_available(self) -> bool:
        if platform.system().lower() != "darwin":
            return False
        p = shutil.which("log")
        return p is not None

    def _run_log_show(self, logarchive_path: Path) -> Iterable[bytes]:
        cmd = ["log", "show", "--style", "json", "--archive", str(logarchive_path)]
        if self.predicate:
            cmd += ["--predicate", self.predicate]
        try:
            proc = subprocess.Popen(cmd, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        except Exception:
            return []
        start = time.time()
        try:
            while True:
                if proc.stdout is None:
                    break
                line = proc.stdout.readline()
                if not line:
                    break
                yield line
                if self.max_entries is not None:
                    self.max_entries -= 1
                    if self.max_entries <= 0:
                        try:
                            proc.terminate()
                        except Exception:
                            pass
                        break
                if time.time() - start > self.timeout_seconds:
                    try:
                        proc.terminate()
                    except Exception:
                        pass
                    break
        finally:
            try:
                if proc.stderr is not None:
                    _ = proc.stderr.read()
            except Exception:
                pass
            try:
                proc.wait(timeout=5)
            except Exception:
                try:
                    proc.kill()
                except Exception:
                    pass

    def extract(self, logarchive_path: Path) -> Iterable[Dict[str, Any]]:
        if not self.is_available():
            return []
        out: List[Dict[str, Any]] = []
        for raw in self._run_log_show(logarchive_path):
            raw = raw.strip()
            if not raw:
                continue
            try:
                if _orjson is not None:
                    obj = _orjson.loads(raw)
                else:
                    obj = json.loads(raw.decode("utf-8", errors="replace"))
                if isinstance(obj, dict):
                    out.append(obj)
            except Exception:
                continue
        return out

def is_within_directory(directory: Path, target: Path) -> bool:
    try:
        directory = directory.resolve()
        target = target.resolve()
        return str(target).startswith(str(directory) + os.sep) or target == directory
    except Exception:
        return False

def safe_extract_tar(tar: tarfile.TarFile, path: Path) -> None:
    safe_mkdir(path)
    for member in tar.getmembers():
        member_path = path / member.name
        if not is_within_directory(path, member_path):
            raise RuntimeError("Unsafe tar path traversal detected")
        if member.islnk() or member.issym():
            raise RuntimeError("Unsafe tar link entry detected")
    tar.extractall(path)

def safe_extract_zip(zf: zipfile.ZipFile, path: Path) -> None:
    safe_mkdir(path)
    for name in zf.namelist():
        target = path / name
        if not is_within_directory(path, target):
            raise RuntimeError("Unsafe zip path traversal detected")
    zf.extractall(path)

def find_latest_candidate(base: Path) -> Optional[Path]:
    candidates: List[Path] = []
    for p in base.rglob("*"):
        try:
            if p.is_dir():
                n = p.name.lower()
                if "sysdiagnose" in n or n.endswith(".logarchive") or "diagnose" in n or n.startswith("extract"):
                    candidates.append(p)
        except Exception:
            continue
    if not candidates:
        return None
    candidates.sort(key=lambda x: x.stat().st_mtime, reverse=True)
    return candidates[0]

def find_latest_archive(base: Path) -> Optional[Path]:
    cands: List[Path] = []
    pats = ["*.tar.gz", "*.tgz", "*.tar", "*.zip"]
    for pat in pats:
        for p in base.rglob(pat):
            try:
                if p.is_file():
                    cands.append(p)
            except Exception:
                continue
    if not cands:
        return None
    cands.sort(key=lambda x: x.stat().st_mtime, reverse=True)
    return cands[0]

def prepare_root(input_path: Optional[str], work_dir: Path) -> Tuple[Path, Optional[Path]]:
    base = Path(input_path).expanduser().resolve() if input_path else Path.cwd().resolve()
    logarchive_hint: Optional[Path] = None
    if base.is_file():
        lower = base.name.lower()
        if lower.endswith((".tar.gz", ".tgz", ".tar")):
            extract_dir = work_dir / f"extract_{int(time.time())}"
            with tarfile.open(base, "r:*") as tar:
                safe_extract_tar(tar, extract_dir)
            cand = find_latest_candidate(extract_dir)
            root = cand if cand is not None else extract_dir
            la = next((p for p in root.rglob("*.logarchive") if p.is_dir()), None)
            if la is not None:
                logarchive_hint = la
            return root, logarchive_hint
        if lower.endswith(".zip"):
            extract_dir = work_dir / f"extract_{int(time.time())}"
            with zipfile.ZipFile(base, "r") as zf:
                safe_extract_zip(zf, extract_dir)
            cand = find_latest_candidate(extract_dir)
            root = cand if cand is not None else extract_dir
            la = next((p for p in root.rglob("*.logarchive") if p.is_dir()), None)
            if la is not None:
                logarchive_hint = la
            return root, logarchive_hint
        raise RuntimeError("Unsupported input file")
    if base.is_dir():
        cand = find_latest_candidate(base)
        root = cand if cand is not None else base
        la = next((p for p in root.rglob("*.logarchive") if p.is_dir()), None)
        if la is not None:
            logarchive_hint = la
        if cand is None:
            arc = find_latest_archive(base)
            if arc is not None and arc.is_file():
                return prepare_root(str(arc), work_dir)
        return root, logarchive_hint
    raise RuntimeError("Input path not found")

class ForensicAnalyzer:
    def __init__(
        self,
        root_path: Path,
        output_path: Path,
        max_workers: int,
        follow_symlinks: bool,
        scan_binary_strings: bool,
        max_binary_strings_bytes: Optional[int],
        unified_log_enabled: bool,
        unified_log_max_entries: Optional[int],
        unified_log_predicate: Optional[str],
        unified_log_timeout_seconds: int,
        max_text_lines_per_file: Optional[int],
        max_file_bytes_for_text: Optional[int],
    ) -> None:
        self.root = root_path.resolve()
        self.output = output_path.resolve()
        safe_mkdir(self.output)
        self.max_workers = max(1, int(max_workers))
        self.follow_symlinks = bool(follow_symlinks)
        self.scan_binary_strings = bool(scan_binary_strings)
        self.max_binary_strings_bytes = max_binary_strings_bytes
        self.unified_log_enabled = bool(unified_log_enabled)
        self.unified_log_max_entries = unified_log_max_entries
        self.unified_log_predicate = unified_log_predicate
        self.unified_log_timeout_seconds = unified_log_timeout_seconds
        self.max_text_lines_per_file = max_text_lines_per_file
        self.max_file_bytes_for_text = max_file_bytes_for_text
        self.iocs = IOCStore()
        self.events_writer = EventWriter(self.output)
        self.inventory_writer = InventoryWriter(self.output)
        self.term_matcher = TermMatcher(SURVEILLANCE_TERMS)
        self._stop = threading.Event()
        self._files_scanned_lock = threading.Lock()
        self._files_scanned = 0
        self._start_time = time.time()
        self._errors_lock = threading.Lock()
        self._errors: List[str] = []
        self._unified_extractor = UnifiedLogExtractor(
            output_dir=self.output,
