                    category="NETWORK",
                    subcategory="IPV6",
                    file_path=file_rel,
                    line_offset=line_num,
                    raw_line=s,
                    normalized_line=s_lower,
                    severity="MEDIUM",
                    confidence="MEDIUM",
                    iocs={"ip": ipn},
                    file_sha256=file_sha,
