                    category="CRITICAL",
                    subcategory="IMEI",
                    file_path=file_rel,
                    line_offset=line_num,
                    raw_line=s,
                    normalized_line=s_lower,
                    severity="CRITICAL",
                    confidence="HIGH",
                    iocs={"imei": candidate},
                    file_sha256=file_sha,
                    file_entropy=file_ent,
