def luhn_checksum_ok(digits: str) -> bool:
    s = 0
    alt = False
    for ch in reversed(digits):
        if not ch.isdigit():
            return False
        d = ord(ch) - 48
        if alt:
            d *= 2
            if d > 9:
                d -= 9
        s += d
        alt = not alt
    return s % 10 == 0

def extract_timestamp(line: str) -> Optional[str]:
    m = ISO_TS_RE.search(line)
    if m:
        return m.group(1)
    m = YMD_HMS_RE.search(line)
    if m:
        txt = m.group(1)
        for fmt in ("%Y-%m-%d %H:%M:%S", "%Y-%m-%dT%H:%M:%S"):
            try:
                return datetime.strptime(txt, fmt).isoformat()
            except Exception:
                pass
        return txt
    m = SYSLOG_TS_RE.search(line)
    if m:
        s = m.group(1)
        try:
            return datetime.strptime(f"{datetime.now().year} {s}", "%Y %b %d %H:%M:%S").isoformat()
        except Exception:
            return s
    return None

def valid_ipv4(s: str) -> bool:
    parts = s.split(".")
    if len(parts) != 4:
        return False
    try:
        for p in parts:
            if p == "":
                return False
            n = int(p)
            if n < 0 or n > 255:
                return False
        return True
    except Exception:
        return False

def normalize_ip(s: str) -> Optional[str]:
    s = s.strip()
    try:
        ip = ipaddress.ip_address(s)
        return str(ip)
    except Exception:
        if valid_ipv4(s):
            return s
        return None

