            ext = _tldextract.extract(d)
            if ext.suffix:
                return ".".join([p for p in [ext.subdomain, ext.domain, ext.suffix] if p]).lower()
        except Exception:
            pass
    return d

def guess_file_kind(path: Path) -> str:
    name = path.name.lower()
    suf = path.suffix.lower()
    if name.endswith(".logarchive") or suf == ".logarchive":
        return "logarchive"
    if suf in {".plist", ".mobileconfig"}:
        return "plist"
    if suf in {".db", ".sqlite", ".sqlite3"}:
        return "sqlite"
    if suf in {".json"}:
        return "json"
    if suf in {".txt", ".log"}:
        return "text"
    if suf in {".tracev3"}:
        return "tracev3"
    if suf in {".gz", ".tgz"}:
        return "gzip"
    if suf in {".tar"}:
        return "tar"
    if suf in {".zip"}:
        return "zip"
    return "unknown"

class EntropyCalculator:
    def __init__(self) -> None:
        self.counts = [0] * 256
        self.total = 0

    def update(self,  bytes) -> None:
        self.total += len(data)
        for b in 
            self.counts[b] += 1

    def entropy(self) -> float:
        if self.total == 0:
            return 0.0
        ent = 0.0
        inv_total = 1.0 / float(self.total)
        for c in self.counts:
            if c:
                p = c * inv_total
                ent -= p * math.log2(p)
        return ent

def classify_mime(path: Path, entropy: float) -> str:
    if _magic is not None:
        try:
            m = _magic.Magic(mime=True)
            t = m.from_file(str(path))
            if t:
                return t
        except Exception:
            pass
    if entropy > 7.8:
        return "application/octet-stream; entropy=high"
    if entropy > 6.8:
        return "application/octet-stream"
    return "text/plain"

class IOCStore:
    def __init__(self) -> None:
        self._lock = threading.Lock()
        self._store: Dict[Tuple[str, str], IOCRecord] = {}

    def add(self, ioc_type: str, value: str, file_path: str, ts: Optional[str]) -> None:
        if not ioc_type or value is None:
            return
        v = str(value)
        key = (ioc_type, v)
        with self._lock:
            rec = self._store.get(key)
            if rec is None:
                rec = IOCRecord(type=ioc_type, value=v, count=0, files=[], first_seen=ts, last_seen=ts)
                self._store[key] = rec
            rec.count += 1
            if file_path not in rec.files:
                rec.files.append(file_path)
            if ts:
                if rec.first_seen is None:
                    rec.first_seen = ts
                rec.last_seen = ts

    def to_list(self) -> List[Dict[str, Any]]:
        with self._lock:
            items = list(self._store.values())
        items.sort(key=lambda r: (r.type, -r.count, r.value))
        return [asdict(r) for r in items]

class EventWriter:
    def __init__(self, out_dir: Path) -> None:
        self.out_dir = out_dir
        safe_mkdir(out_dir)
        self._lock = threading.Lock()
        self._fh_events = open(out_dir / "events.jsonl", "ab", buffering=0)
        self._fh_by_cat: Dict[str, Any] = {}
        self.total_events = 0
        self.counts: Dict[str, int] = {}

    def _fh_for_category(self, cat: str) -> Any:
        key = cat.upper()
        fh = self._fh_by_cat.get(key)
        if fh is None:
            fh = open(self.out_dir / f"events_{key}.jsonl", "ab", buffering=0)
            self._fh_by_cat[key] = fh
        return fh

    def write_event(self, event: ForensicEvent) -> None:
        b = _json_line(asdict(event))
        with self._lock:
            self._fh_events.write(b)
            self._fh_for_category(event.category).write(b)
            self.total_events += 1
            self.counts[event.category] = self.counts.get(event.category, 0) + 1

    def close(self) -> None:
        with self._lock:
            try:
                self._fh_events.close()
            except Exception:
                pass
            for fh in self._fh_by_cat.values():
                try:
                    fh.close()
                except Exception:
                    pass
            self._fh_by_cat.clear()

